// src/api/tmdbApi.js
import axios from "axios";

const TMDB_API_KEY = "b56be59cfcfc26fbad50e51fb6341736"; // 발급받은 키 입력
const TMDB_BASE_URL = "https://api.themoviedb.org/3";

// 🎯 개봉일 정밀 비교 + fallback 처리
export const getPosterFromTMDB = async (movieTitle, openDate) => {
    try {
      const response = await axios.get(`${BASE_URL}/search/movie`, {
        params: {
          api_key: TMDB_API_KEY,
          query: movieTitle,
          language: "ko-KR",
        },
      });
  
      const results = response.data.results;
      if (results.length === 0) return null;
  
      // 1. 정확히 개봉일이 같은 영화 우선
      let matched = results.find((movie) => movie.release_date === openDate);
  
      // 2. 없으면 연도만 비교
      if (!matched && openDate) {
        matched = results.find((movie) =>
          movie.release_date?.startsWith(openDate.slice(0, 4))
        );
      }
  
      // 3. 그래도 없으면 첫 번째 결과
      const target = matched || results[0];
  
      // 4. 개봉일 차이가 너무 크면 무시 (예: 1년 이상)
      if (
        openDate &&
        target?.release_date &&
        Math.abs(new Date(openDate) - new Date(target.release_date)) >
          1000 * 60 * 60 * 24 * 365
      ) {
        return null;
      }
  
      // 5. 포스터가 있으면 반환
      return target.poster_path
        ? `https://image.tmdb.org/t/p/w500${target.poster_path}`
        : null;
    } catch (error) {
      console.error("TMDB 포스터 가져오기 실패:", error);
      return null;
    }
  };
